          INC: { a: 188, dpX: 187, dp: 171, abs: 172 },
          LSR: { a: 92, dpX: 91, dp: 75, abs: 76 },
          ROL: { a: 60, dpX: 59, dp: 43, abs: 44 },
          ROR: { a: 124, dpX: 123, dp: 107, abs: 108 }
